"""
    :param string:string
    :return: permutation list
    """
def string_permutation(string: Any) -> object {
    """
        :param pre_s: n-1 sol
        :param string: str waiting to add
        :return: n sol
        """;
    def recursion_core(pre_s: Any, string: Any) -> object {
        if not string {
            ans.append(pre_s);
            return;
        }
        for s in range(len(string)) {
            recursion_core((pre_s + string[s]), (string[:s] + string[(s + 1):]));
        }
    }
    ans = [];
    recursion_core('', string);
    return ans;
}

